class Solution:
    def minAbsDifference(self, nums):
        last1 = last2 = -1
        ans = float('inf')
        for i, x in enumerate(nums):
            if x == 1:
                if last2 >= 0:
                    ans = min(ans, i - last2)
                last1 = i
            elif x == 2:
                if last1 >= 0:
                    ans = min(ans, i - last1)
                last2 = i
        return ans if ans != float('inf') else -1

