class Solution {
public:
    int minAbsDifference(vector<int>& nums) {
        int last1 = -1, last2 = -1, ans = INT_MAX;
        for (int i = 0; i < (int)nums.size(); i++) {
            if (nums[i] == 1) {
                if (last2 >= 0) ans = min(ans, i - last2);
                last1 = i;
            } else if (nums[i] == 2) {
                if (last1 >= 0) ans = min(ans, i - last1);
                last2 = i;
            }
        }
        return ans == INT_MAX ? -1 : ans;
    }
};

